#define N 1024
int A[N][N];

// Good: Row-major access (High Spatial Locality)
// Loads one cache line, uses all data in it.
for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
        A[i][j]++;
    }
}

// Bad: Column-major access (Poor Stride)
// Accesses N locations separated by large distances, thrashing the cache.
for (int j = 0; j < N; j++) {
    for (int i = 0; i < N; i++) {
        A[i][j]++;
    }
}

// Temporal Locality Example (Reusing cache line)
int sum = 0;
