// VIRTUAL MEMORY: Independent Address Spaces (MMU Model)

typedef struct {
    unsigned int PFN : 20;  // Physical Frame Number
    unsigned int Valid : 1; // Presence in RAM
    unsigned int R_W : 1;   // Access bits
} PageTableEntry;

// CR3/PML4 Base Register holds the current process's mapping
PageTableEntry* Current_CR3_Register;

#define PAGE_OFFSET_MASK 0xFFF
#define PAGE_SHIFT 12 // 4KB pages

unsigned long Translate_VA_to_PA(unsigned long va) {
    unsigned long page_num = va >> PAGE_SHIFT;
    unsigned long offset   = va & PAGE_OFFSET_MASK;

    PageTableEntry pte = Current_CR3_Register[page_num];

    if (!pte.Valid) { /* OS handles Page Fault/Swap */ return 0; }

    return (pte.PFN << PAGE_SHIFT) | offset;
}

