float dot_prod_optimized(float* A, float* B, int N) {
    // Four independent accumulators to minimize dependency stalls (ILP)
    float s0 = 0.0f, s1 = 0.0f;
    float s2 = 0.0f, s3 = 0.0f;

    // Loop Unrolling (Factor 4)
    for (int i = 0; i < N; i += 4) {

        // Operation Reordering: Utilize separate registers/pipelines
        // s0, s1, s2, s3 updates proceed in parallel without waiting
        s0 += A[i]   * B[i];
        s1 += A[i+1] * B[i+1];
        s2 += A[i+2] * B[i+2];
        s3 += A[i+3] * B[i+3];
    }

    // Final reduction step (sequential, minimal overhead)
    return s0 + s1 + s2 + s3;
}
