float parallel_sum(const float* V, int N) {
    // Standard approach: sum += V[i] (High dependency)

    // Reassociated approach: Two accumulators S0, S1
    float S0 = 0.0f;
    float S1 = 0.0f;

    for (int i = 0; i < N; i += 2) {
        S0 += V[i];
        S1 += V[i+1];
    }
