// 1. Spatial Locality (Sequential Memory Access)
#define N 100
int matrix[N][N];

// Excellent Spatial Locality (Row-Major access in C/C++)
// Loads cache line containing several adjacent matrix elements
for (int i = 0; i < N; ++i) {
    for (int j = 0; j < N; ++j) {
