#define BITS_PER_UNIT 8
#define MAX_RESOURCES 512

// Bitmap uses 64 bytes (512 / 8)
unsigned char resource_map[MAX_RESOURCES / BITS_PER_UNIT];

// Index calculations
#define GET_BYTE(n) (n / BITS_PER_UNIT)
#define GET_BIT(n)  (1 << (n % BITS_PER_UNIT))

// Check status (Returns 1 if allocated)
int is_allocated(int n) {
    return resource_map[GET_BYTE(n)] & GET_BIT(n);
}

// Set bit (Allocate resource)
void set_bit(int n) {
    resource_map[GET_BYTE(n)] |= GET_BIT(n);
}

// Clear bit (Free resource)
void clear_bit(int n) {
    resource_map[GET_BYTE(n)] &= ~GET_BIT(n);
}
