concept_012_object_memory_layout_and_con.code:
struct Object {
    int id;
    Object(int i) : id(i) {} // Constructor invoked sequentially
};

const size_t N = 3;
const size_t OBJ_SIZE = sizeof(Object);

// 1. Allocate raw memory (large enough for N objects)
char* raw_mem = new char[N * OBJ_SIZE];

// 2. Sequential Construction (Compiler mechanism shown manually)
for (size_t i = 0; i < N; ++i) {
    // Calculate contiguous address
    void* addr = raw_mem + (i * OBJ_SIZE);

    // Invoke Object constructor at calculated address (placement new)
    new (addr) Object{ (int)i };
}

// Memory Layout: [Obj 0] [Obj 1] [Obj 2]
// &Obj[i] == &Obj[i-1] + OBJ_SIZE
